import React, { useState } from 'react';
import {
  Box,
  Typography,
  Divider,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Switch,
  FormControlLabel,
  IconButton,
  Chip,
  Snackbar,
  Alert
} from '@mui/material';
import Accordion from '@mui/material/Accordion';
import AccordionSummary from '@mui/material/AccordionSummary';
import AccordionDetails from '@mui/material/AccordionDetails';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import CloseIcon from '@mui/icons-material/Close';

const FrameDetailsPage = ({ frames = [], onBack = () => {} }) => {
  const [onlyViolations, setOnlyViolations] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewSrc, setPreviewSrc] = useState('');
  const [toast, setToast] = useState({ open: false, severity: 'success', message: '' });

  const formatTs = (s) => {
    if (s === undefined || s === null || isNaN(Number(s))) return 'N/A';
    const total = Number(s);
    const ms = Math.floor((total % 1) * 1000);
    const sec = Math.floor(total % 60);
    const min = Math.floor((total / 60) % 60);
    const hr = Math.floor(total / 3600);
    return `${String(hr).padStart(2,'0')}:${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;
  };

  const openPreview = (src) => { setPreviewSrc(src); setPreviewOpen(true); };
  const closePreview = () => { setPreviewOpen(false); setPreviewSrc(''); };

  if (!frames || frames.length === 0) {
    return (
      <Box sx={{ p: 4 }}>
        <Button variant="outlined" onClick={onBack} sx={{ mb: 2 }}>← Back</Button>
        <Typography>No frames found.</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Button variant="outlined" onClick={onBack} sx={{ mb: 2 }}>← Back</Button>
      <Typography variant="h5" sx={{ mb: 2 }}>Detailed Frame Report</Typography>

      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <FormControlLabel control={<Switch checked={onlyViolations} onChange={(e) => setOnlyViolations(e.target.checked)} />} label="Only show violations" />
        <Box>
          <Chip label={`Frames: ${frames.length}`} size="small" sx={{ mr: 1 }} />
        </Box>
      </Box>

      {frames.filter(f => !onlyViolations || f.__isViolation).map((frame, idx) => (
        <Accordion key={idx} defaultExpanded={Boolean(frame.__isViolation)} sx={{ mb: 2 }}>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
              <Box sx={{ width: 140 }}>
                {frame.preview_path ? (
                  <img src={frame.preview_path} alt={`frame-${idx}`} style={{ width: 140, height: 90, objectFit: 'cover', borderRadius: 6, cursor: 'pointer' }} onClick={() => openPreview(frame.preview_path)} />
                ) : (
                  <Box sx={{ width: 140, height: 90, background: '#f5f5f5', borderRadius: 1 }} />
                )}
              </Box>

              <Box sx={{ flex: 1 }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                  Frame {frame.frame_index !== undefined ? frame.frame_index + 1 : idx + 1}
                  <small style={{ marginLeft: 8 }}>{formatTs(frame.timestamp)}</small>
                </Typography>

                <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', mt: 0.5 }}>
                  <Chip label={frame.__isViolation ? 'VIOLATION' : 'SAFE'} color={frame.__isViolation ? 'error' : 'success'} size="small" />
                  <Typography variant="caption">{frame.visual_analysis?.category || frame.category || 'N/A'}</Typography>
                  <Typography variant="caption" sx={{ ml: 2 }}>Conf: {frame.visual_analysis?.confidence !== undefined ? Number(frame.visual_analysis.confidence).toFixed(2) : frame.confidence || 'N/A'}</Typography>
                </Box>

                <Typography variant="body2" noWrap sx={{ mt: 0.5 }}>
                  {frame.rag_decision?.explanation?.evidence?.visual_result?.blip || frame.blip_description?.description || frame.blip || frame.ocr_text?.text || frame.ocr || 'No evidence'}
                </Typography>
              </Box>
            </Box>
          </AccordionSummary>

          <AccordionDetails>
            <Box>
              <Typography variant="body2">Category: <b>{frame.__isViolation ? 'BAD CONTENT' : (frame.visual_analysis?.category || frame.category || 'N/A')}</b></Typography>
              <Typography variant="body2">Confidence: <b>{frame.visual_analysis?.confidence !== undefined ? frame.visual_analysis.confidence : frame.confidence || 'N/A'}</b></Typography>
              <Divider sx={{ my: 1 }} />

              <Typography variant="body2">BLIP Description: <b>{frame.blip_description?.description || 'N/A'}</b></Typography>
              {frame.blip && <Typography variant="body2">Model BLIP: <b>{frame.blip}</b></Typography>}
              {frame.rag_decision?.explanation?.evidence?.visual_result?.blip && <Typography variant="body2">RAG BLIP: <b>{frame.rag_decision.explanation.evidence.visual_result.blip}</b></Typography>}

              <Divider sx={{ my: 1 }} />

              <Typography variant="body2">OCR Text: <b>{frame.ocr_text?.text || 'N/A'}</b></Typography>
              {frame.ocr && <Typography variant="body2">Model OCR: <b>{frame.ocr}</b></Typography>}
              {frame.rag_decision?.explanation?.evidence?.visual_result?.ocr && <Typography variant="body2">RAG OCR: <b>{frame.rag_decision.explanation.evidence.visual_result.ocr}</b></Typography>}

              {Array.isArray(frame.retrieved_policies) && frame.retrieved_policies.length > 0 && (
                <Box component="ul" sx={{ pl: 2, mt: 1 }}>
                  {frame.retrieved_policies.map((p, i) => (
                    <Box component="li" key={i}>
                      <Typography variant="body2"><strong>{p.policy_info?.category || p.category || 'policy'}</strong> — {p.policy_info?.title || p.policy_info?.description || p.description || 'No description'}</Typography>
                      <Typography variant="caption" color="text.secondary">Source: {p.source || p.policy_info?.source || 'database'} | sim: {p.similarity !== undefined ? Number(p.similarity).toFixed(3) : 'N/A'}</Typography>
                    </Box>
                  ))}
                </Box>
              )}

              {frame.rag_decision && frame.rag_decision.explanation && (
                <Box sx={{ mt: 1, p: 1, borderRadius: 1, background: '#fbfbff', border: '1px solid rgba(0,0,0,0.06)' }}>
                  <Typography variant="subtitle2">RAG Explanation</Typography>
                  {frame.rag_decision.explanation.verdict_summary && <Typography variant="body2" sx={{ mt: 0.5 }}><strong>{frame.rag_decision.explanation.verdict_summary}</strong></Typography>}
                  {frame.rag_decision.explanation.primary_policy && (
                    <Box sx={{ mt: 1 }}>
                      <Typography variant="body2"><strong>Primary policy:</strong> {frame.rag_decision.explanation.primary_policy.category} <small>({Number(frame.rag_decision.explanation.primary_policy.similarity || 0).toFixed(3)})</small></Typography>
                      {frame.rag_decision.explanation.primary_policy.policy_text_snippet && <Typography variant="body2" sx={{ mt: 0.5 }}>{frame.rag_decision.explanation.primary_policy.policy_text_snippet}</Typography>}
                    </Box>
                  )}
                </Box>
              )}

              <Divider sx={{ my: 1 }} />
              <Typography variant="body2">Preview Path: <b>{frame.preview_path || 'N/A'}</b></Typography>
              <Typography variant="body2">Frame Index: <b>{frame.frame_index !== undefined ? frame.frame_index : idx}</b></Typography>
            </Box>
          </AccordionDetails>
        </Accordion>
      ))}

      {/* Preview dialog */}
      <Dialog open={previewOpen} onClose={closePreview} maxWidth="lg">
        <DialogTitle>
          Frame preview
          <IconButton aria-label="close" onClick={closePreview} sx={{ position: 'absolute', right: 8, top: 8 }}>
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers>
          {previewSrc ? <img src={previewSrc} alt="preview" style={{ maxWidth: '100%', maxHeight: '70vh' }} /> : <Typography>No preview available</Typography>}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => { navigator.clipboard && navigator.clipboard.writeText(previewSrc); setToast({ open: true, severity: 'success', message: 'Frame URL copied' }); }}>Copy URL</Button>
          <Button onClick={closePreview}>Close</Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={toast.open} autoHideDuration={3000} onClose={() => setToast(t => ({ ...t, open: false }))}>
        <Alert severity={toast.severity || 'info'} onClose={() => setToast(t => ({ ...t, open: false }))}>{toast.message}</Alert>
      </Snackbar>
    </Box>
  );
};

export default FrameDetailsPage;
